\"\"\"Private OpenAI Responses API client using only the Python standard library.

Design goals:

* Standard library only ("'``urllib``, ``json``, ``os``, ``time``).
* Private by default: prompts and API keys are never written to disk, never
  logged, never echoed back in error messages, and responses are not stored
  server side (``store=False``) unless you explicitly opt in.
* HTTPS only for real endpoints; plaintext is accepted only for loopback
  addresses so you can test against a local mock server.

Quick start::

    from openai_client import ask
    print(ask("Summarise the privacy risks of session logs."))

Or with a persistent client (reuses TLS connections and conversation state)::

    from openai_client import OpenAIClient

    with OpenAIClient(model="gpt-5") as client:
        first = client.ask("Remember that my favourite colour is green.")
        follow_up = client.ask("What is my favourite colour?",
                               previous_response_id=first.response_id)
        print(follow_up.text)

Command line (the prompt may be piped in to keep it out of your shell
history)::

    printf '"'%s' \"my private question\" | python3 openai_client.py --stream
\"\"\"

from __future__ import annotations

import json
import os
import socket
import ssl
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, Iterator, List, Optional, Sequence, Union

__all__ = [
    \"OpenAIClient\",
    \"Response\",
    \"ask\",
    \"complete\",
    \"stream\",
    \"OpenAIError\",
    \"AuthenticationError\",
    \"RateLimitError\",
    \"APIUnavailableError\",
    \"InvalidRequestError\",
    \"TransportError\",
    \"DEFAULT_MODEL\",
]

DEFAULT_MODEL = \"gpt-5\"
DEFAULT_API_BASE = \"https://api.openai.com/v1\"
DEFAULT_TIMEOUT = 60.0
LOOPBACK_HOSTS = {\"localhost\", \"127.0.0.1\", \"::1\", \"0.0.0.0\"}


# --------------------------------------------------------------------------- #
# Errors
# --------------------------------------------------------------------------- #
class OpenAIError(RuntimeError):
    \"\"\"Base error. Messages are sanitised: they never contain the API key.\"\"\"

    def __init__(self, message: str, status: Optional[int] = None,
                 request_id: Optional[str] = None,
                 payload: Optional[Dict[str, Any]] = None) -> None:
        super().__init__(message)
        self.status = status
        self.request_id = request_id
        self.payload = payload


class AuthenticationError(OpenAIError):
    \"\"\"The API key was rejected (HTTP 401/403).\"\"\"


class InvalidRequestError(OpenAIError):
    \"\"\"The request was malformed or rejected by the API (HTTP 400/404/422).\"\"\"


class RateLimitError(OpenAIError):
    \"\"\"Rate limited (HTTP 429). "'``retry_after`` seconds when advertised."""

    def __init__(self, message: str, retry_after: Optional[float] = None,
                 **kwargs: Any) -> None:
        super().__init__(message, **kwargs)
        self.retry_after = retry_after


class APIUnavailableError(OpenAIError):
    """The API responded with a server-side error (HTTP 5xx)."""


class TransportError(OpenAIError):
    """Network-level failure: DNS, TLS, timeout, connection reset."""


# --------------------------------------------------------------------------- #
# Result helpers
# --------------------------------------------------------------------------- #
@dataclass
class Response:
    """A parsed Responses API result."""

    text: str
    response_id: Optional[str] = None
    model: Optional[str] = None
    usage: Dict[str, Any] = field(default_factory=dict)
    raw: Dict[str, Any] = field(default_factory=dict)

    def __str__(self) -> str:  # keep prints cheap and secret-free
        return self.text


def _extract_text(payload: Dict[str, Any]) -> str:
    """Collect assistant text out of a Responses API payload."""
    chunks: List[str] = []
    for item in payload.get("output") or []:
        if not isinstance(item, dict):
            continue
        if item.get("type") == "error":
            raise InvalidRequestError(
                item.get("error", {}).get("message", "model returned an error")
                if isinstance(item.get("error"), dict)
                else "model returned an error",
                payload=payload,
            )
        for part in item.get("content") or []:
            if not isinstance(part, dict):
                continue
            part_type = part.get("type")
            if part_type in (None, "output_text", "text"):
                value = part.get("text")
            elif part_type == "refusal":
                value = part.get("refusal")
            else:
                value = None
            if isinstance(value, str):
                chunks.append(value)
    if not chunks:
        direct = payload.get("output_text")
        if isinstance(direct, str):
            chunks.append(direct)
    return "".join(chunks)


def _normalize_input(prompt: Union[str, Sequence[Dict[str, Any]]]) -> Union[str, List[Dict[str, Any]]]:
    """Accept a plain string or a list of input items / content parts."""
    if isinstance(prompt, str):
        return prompt
    if isinstance(prompt, Sequence):
        return [dict(part) for part in prompt]
    raise TypeError("prompt must be a string or a sequence of content parts")


# --------------------------------------------------------------------------- #
# Configuration helpers
# --------------------------------------------------------------------------- #
def _resolve_api_key(api_key: [REDACTED_SECRET] -> str:
    if api_key is None:
        api_key = [REDACTED_SECRET]"OPENAI_API_KEY")
    if not api_key:
        raise OpenAIError(
            "No API key found. Set the OPENAI_API_KEY environment variable or "
            "pass api_key=... . Do not hard-code keys in source files."
        )
    return api_key.strip()


def _resolve_base_url(base_url: Optional[str], allow_insecure: bool) -> str:
    if base_url is None:
        base_url = (
            os.environ.get("OPENAI_BASE_URL")
            or os.environ.get("OPENAI_API_BASE")
            or DEFAULT_API_BASE
        )
    parsed = urllib.parse.urlsplit(base_url.strip().rstrip("/"))
    if not parsed.netloc or not parsed.scheme:
        raise OpenAIError(f"Invalid base URL: {base_url!r}")
    if parsed.scheme != "https" and not allow_insecure:
        if parsed.hostname not in LOOPBACK_HOSTS:
            raise OpenAIError(
                "Refusing to send prompts over plaintext HTTP to a non-loopback "
                "host. Use an https:// endpoint or pass allow_insecure=True."
            )
    return base_url.strip().rstrip("/")


def _error_message(payload: Any) -> str:
    if isinstance(payload, dict):
        err = payload.get("error")
        if isinstance(err, dict):
            message = err.get("message")
            if isinstance(message, str) and message:
                return message
        if isinstance(err, str):
            return err
        message = payload.get("message")
        if isinstance(message, str) and message:
            return message
    return "the API returned an unspecified error"


# --------------------------------------------------------------------------- #
# Client
# --------------------------------------------------------------------------- #
class OpenAIClient:
    """Small, private client for ``POST /v1/responses``."""

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        model: Optional[str] = None,
        base_url: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
        store: bool = False,
        max_retries: int = 2,
        headers: Optional[Dict[str, str]] = None,
        allow_insecure: bool = False,
        verify_ssl: bool = True,
    ) -> None:
        self.api_key = [REDACTED_SECRET]
        self.model = model or os.environ.get("OPENAI_MODEL") or DEFAULT_MODEL
        self.base_url = _resolve_base_url(base_url, allow_insecure)
        self.allow_insecure = allow_insecure
        self.timeout = float(timeout)
        self.store = bool(store)
        self.max_retries = max(0, int(max_retries))
        self.verify_ssl = verify_ssl
        self.headers = dict(headers or {})
        for env_name, header in (
            ("OPENAI_ORG_ID", "OpenAI-Organization"),
            ("OPENAI_PROJECT_ID", "OpenAI-Project"),
        ):
            value = os.environ.get(env_name)
            if value:
                self.headers.setdefault(header, value)
        self._opener = self._build_opener()

    # -- plumbing ---------------------------------------------------------- #
    def _build_opener(self) -> urllib.request.OpenerDirector:
        context = None
        if not self.verify_ssl and not self.allow_insecure:
            raise OpenAIError("verify_ssl=False requires allow_insecure=True.")
        if self.base_url.startswith("http://") or not self.verify_ssl:
            context = ssl._create_unverified_context() if not self.verify_ssl else None
        else:
            context = ssl.create_default_context()
        handlers: List[Any] = [urllib.request.HTTPSHandler(context=context)]
        if not self.verify_ssl:
            handlers.append(urllib.request.HTTPHandler(context=context))
        # No ProxyHandler in the chain means proxies are never bypassed for
        # localhost tests, but environment proxies are still respected.
        return urllib.request.build_opener(*handlers)

    def _url(self) -> str:
        return f"{self.base_url}/responses"

    def _request_headers(self, stream: bool) -> Dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "text/event-stream" if stream else "application/json",
            "User-Agent": "openai_client/1.0 python-stdlib",
            "Connection": "close" if stream else "keep-alive",
        }
        headers.update(self.headers)
        return headers

    def build_body(
        self,
        prompt: Union[str, Sequence[Dict[str, Any]]],
        *,
        instructions: Optional[str] = None,
        previous_response_id: Optional[str] = None,
        model: Optional[str] = None,
        store: Optional[bool] = None,
        stream: bool = False,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
        reasoning_effort: Optional[str] = None,
        extra: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Build the JSON request body. Exposed for tests and debugging."""
        body: Dict[str, Any] = {
            "model": model or self.model,
            "input": _normalize_input(prompt),
            "stream": bool(stream),
            # Privacy default: ask the API not to retain the conversation.
            "store": self.store if store is None else bool(store),
        }
        if instructions:
            body["instructions"] = instructions
        if previous_response_id:
            body["previous_response_id"] = previous_response_id
        if max_output_tokens is not None:
            body["max_output_tokens"] = int(max_output_tokens)
        if temperature is not None:
            body["temperature"] = float(temperature)
        if reasoning_effort:
            body["reasoning"] = {"effort": reasoning_effort}
        if extra:
            body.update(extra)
        return body

    def _send(self, body: Dict[str, Any], stream: bool):
        """POST the body, retrying transient failures. Returns a live file obj."""
        data = json.dumps(body).encode("utf-8")
        last_error: Optional[BaseException] = None
        for attempt in range(self.max_retries + 1):
            request = urllib.request.Request(
                self._url(), data=data,
                headers=self._request_headers(stream), method="POST")
            try:
                return self._opener.open(request, timeout=self.timeout)
            except urllib.error.HTTPError as exc:  # non-2xx
                retryable = 500 <= exc.code < 600 or exc.code == 429
                advertised = exc.headers.get("x-should-retry")
                if advertised is not None:
                    retryable = advertised.lower() == "true" or retryable
                if retryable and attempt < self.max_retries:
                    delay = self._retry_delay(exc, attempt)
                    exc.close()
                    time.sleep(delay)
                    last_error = exc
                    continue
                raise self._http_error(exc) from None
            except (urllib.error.URLError, socket.timeout, ssl.SSLError,
                    OSError) as exc:  # DNS, TLS, refused connection, timeout
                reason = getattr(exc, "reason", exc)
                if isinstance(reason, ssl.SSLCertVerificationError):
                    raise TransportError(
                        f"TLS certificate verification failed: {reason.verify_code}."
                    ) from None
                if isinstance(exc, urllib.error.HTTPError):
                    raise self._http_error(exc) from None
                if attempt < self.max_retries:
                    time.sleep(min(2.0 ** attempt, 4.0))
                    last_error = exc
                    continue
                # Keep the message generic: never embed URL query secrets or keys.
                raise TransportError(
                    f"Could not reach {urllib.parse.urlsplit(self._url()).netloc}: "
                    f"{type(reason).__name__ if not isinstance(reason, str) else reason}"
                ) from None
        raise TransportError(f"Request failed after retries: {last_error!r}")

    @staticmethod
    def _retry_delay(exc: urllib.error.HTTPError, attempt: int) -> float:
        retry_after = exc.headers.get("retry-after")
        if retry_after:
            try:
                return min(float(retry_after), 60.0)
            except ValueError:
                pass
        return min(2.0 ** attempt, 8.0)

    def _http_error(self, exc: urllib.error.HTTPError) -> OpenAIError:
        body_bytes = exc.read() if exc.fp is not None else b""
        try:
            payload = json.loads(body_bytes.decode("utf-8")) if body_bytes else {}
        except (ValueError, UnicodeDecodeError):
            payload = {}
        request_id = exc.headers.get("x-request-id")
        message = _error_message(payload) or f"HTTP {exc.code}"
        # Never include the outbound Authorization header in the message.
        common = {"status": exc.code, "request_id": request_id, "payload": payload}
        if exc.code in (401, 403):
            return AuthenticationError(f"Authentication failed ({exc.code}): {message}", **common)
        if exc.code == 429:
            retry_after = exc.headers.get("retry-after")
            return RateLimitError(
                f"Rate limited: {message}",
                retry_after=float(retry_after) if retry_after else None, **common)
        if 500 <= exc.code < 600:
            return APIUnavailableError(f"API unavailable ({exc.code}): {message}", **common)
        return InvalidRequestError(f"Request rejected ({exc.code}): {message}", **common)

    # -- public API -------------------------------------------------------- #
    def complete(self, prompt: Union[str, Sequence[Dict[str, Any]]],
                 **kwargs: Any) -> Response:
        """Send one prompt and return the full parsed :class:`Response`."""
        kwargs.pop("stream", None)
        body = self.build_body(prompt, stream=False, **kwargs)
        with self._send(body, stream=False) as handle:
            payload = json.loads(handle.read().decode("utf-8"))
        return Response(
            text=_extract_text(payload),
            response_id=payload.get("id"),
            model=payload.get("model"),
            usage=payload.get("usage") or {},
            raw=payload,
        )

    def stream(self, prompt: Union[str, Sequence[Dict[str, Any]]],
               **kwargs: Any) -> Iterator[str]:
        """Send one prompt and yield text deltas as they arrive."""
        kwargs.pop("stream", None)
        body = self.build_body(prompt, stream=True, **kwargs)
        handle = self._send(body, stream=True)
        try:
            for name, data in _iter_sse(handle):
                if name == "error" or (data.get("type") == "error"):
                    raise APIUnavailableError(_error_message(data) or "stream error",
                                              payload=data)
                if name == "response.output_text.delta":
                    delta = data.get("delta")
                    if isinstance(delta, str):
                        yield delta
                elif name == "response.completed":
                    break
        finally:
            handle.close()

    def ask(self, prompt: Union[str, Sequence[Dict[str, Any]]],
            **kwargs: Any) -> Response:
        """Alias of :meth:`complete` that reads naturally in scripts."""
        return self.complete(prompt, **kwargs)

    def send_prompt(self, prompt: str, **kwargs: Any) -> str:
        """Backwards-friendly helper returning just the text."""
        return self.complete(prompt, **kwargs).text

    def close(self) -> None:
        self._opener.close()

    def __enter__(self) -> "OpenAIClient":
        return self

    def __exit__(self, *exc_info: Any) -> None:
        self.close()


def _iter_sse(lines: Iterable[bytes]) -> Iterator[tuple]:
    """Yield ``(event_name, json_payload)`` pairs from an SSE byte stream."""
    event_name = ""
    data_lines: List[str] = []
    for raw in lines:
        line = raw.decode("utf-8", "replace").rstrip("'"\\r\\n\")
        if not line:
            if data_lines:
                try:
                    payload = json.loads(\"\\n\".join(data_lines))
                except ValueError:
                    payload = {}
                yield event_name, payload
            event_name, data_lines = \"\", []
            continue
        if line.startswith(\":\"):
            continue  # comment / keep-alive
        if line.startswith(\"event:\"):
            event_name = line[len(\"event:\"):].strip()
        elif line.startswith(\"data:\"):
            data_lines.append(line[len(\"data:\"):].lstrip())
    if data_lines:
        try:
            yield event_name, json.loads(\"\\n\".join(data_lines))
        except ValueError:
            yield event_name, {}


# --------------------------------------------------------------------------- #
# Module-level convenience functions (one client per call)
# --------------------------------------------------------------------------- #
def ask(prompt: Union[str, Sequence[Dict[str, Any]]], **kwargs: Any) -> Response:
    client_kwargs = {k: kwargs.pop(k) for k in
                     (\"api_key\", \"model\", \"base_url\", \"timeout\", \"store\",
                      \"max_retries\", \"headers\", \"allow_insecure\", \"verify_ssl\")
                     if k in kwargs}
    with OpenAIClient(**client_kwargs) as client:
        return client.complete(prompt, **kwargs)


def complete(prompt: Union[str, Sequence[Dict[str, Any]]], **kwargs: Any) -> Response:
    return ask(prompt, **kwargs)


def stream(prompt: Union[str, Sequence[Dict[str, Any]]], **kwargs: Any) -> Iterator[str]:
    client_kwargs = {k: kwargs.pop(k) for k in
                     (\"api_key\", \"model\", \"base_url\", \"timeout\", \"store\",
                      \"max_retries\", \"headers\", \"allow_insecure\", \"verify_ssl\")
                     if k in kwargs}
    client = OpenAIClient(**client_kwargs)
    try:
        yield from client.stream(prompt, **kwargs)
    finally:
        client.close()


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #
def main(argv: Optional[List[str]] = None) -> int:
    import argparse

    parser = argparse.ArgumentParser(
        prog=\"openai_client.py\",
        description=\"Send a private prompt to the OpenAI Responses API.\")
    parser.add_argument(\"prompt\", nargs=\"?\", default=\"-\",
                        help=\"Prompt text, or '-' to read stdin (default).\")
    parser.add_argument(\"--model\", default=None)
    parser.add_argument(\"--instructions\", default=None,
                        help=\"System-level instructions for this request.\")
    parser.add_argument(\"--base-url\", default=None)
    parser.add_argument(\"--timeout\", type=float, default=DEFAULT_TIMEOUT)
    parser.add_argument(\"--max-retries\", type=int, default=2)
    parser.add_argument(\"--temperature\", type=float, default=None)
    parser.add_argument(\"--max-output-tokens\", type=int, default=None)
    parser.add_argument(\"--reasoning-effort\", default=None,
                        choices=[\"minimal\", \"low\", \"medium\", \"high\"])
    parser.add_argument(\"--previous-response-id\", default=None,
                        help=\"Continue a previous conversation.\")
    parser.add_argument(\"--store\", action=\"store_true\",
                        help=\"Opt in to server-side retention of this response.\")
    parser.add_argument(\"--stream\", action=\"store_true\",
                        help=\"Print tokens as they arrive.\")
    parser.add_argument(\"--json\", action=\"store_true\", dest=\"as_json\",
                        help=\"Print the raw API JSON instead of just the text.\")
    args = parser.parse_args(argv)

    if args.prompt == \"-\":
        prompt = sys.stdin.read()
    else:
        prompt = args.prompt
    if not prompt.strip():
        print(\"error: empty prompt\", file=sys.stderr)
        return 2

    call_kwargs: Dict[str, Any] = {
        \"timeout\": args.timeout,
        \"max_retries\": args.max_retries,
        \"store\": args.store,
        \"instructions\": args.instructions,
        \"previous_response_id\": args.previous_response_id,
        \"temperature\": args.temperature,
        \"max_output_tokens\": args.max_output_tokens,
        \"reasoning_effort\": args.reasoning_effort,
    }
    call_kwargs = {k: v for k, v in call_kwargs.items() if v is not None}

    try:
        client = OpenAIClient(model=args.model, base_url=args.base_url)
    except OpenAIError as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        return 1

    try:
        with client:
            if args.stream:
                for delta in client.stream(prompt, **call_kwargs):
                    sys.stdout.write(delta)
                    sys.stdout.flush()
                sys.stdout.write(\"\\n\")
            else:
                result = client.complete(prompt, **call_kwargs)
                if args.as_json:
                    json.dump(result.raw, sys.stdout, indent=2, sort_keys=True)
                    sys.stdout.write(\"\\n\")
                else:
                    sys.stdout.write(result.text)
                    if not result.text.endswith(\"\\n\"):
                        sys.stdout.write(\"\\n\")
    except OpenAIError as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        if exc.request_id:
            print(f\"request id: {exc.request_id}\", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print(\"interrupted\", file=sys.stderr)
        return 130
    return 0


if __name__ == \"__main__\":
    sys.exit(main())
